"""Author the matching spa fixture kit in Blender. No geometry is generated by the browser.

KayKit's gradient-textured, soft low-poly furniture is the art reference. Beveled
edges, restrained gradients, uniform texel-free materials and shared proportions
keep these spa-specific additions in the same visual language.
Run: blender --background --python tools/bake-spa.py
"""
import bpy, math, random
from pathlib import Path
from mathutils import Vector

OUT = Path(__file__).resolve().parents[1] / 'godot/assets/spa'
OUT.mkdir(parents=True, exist_ok=True)
random.seed(18)
PALETTE = {'cream':'E4D9BD','stone':'C8C5AF','edge':'ADA995','wood':'AF805D',
           'darkwood':'735547','cedar':'C49872','sage':'8DAB95','teal':'528F89',
           'clay':'C48972','linen':'E9DFCA','gold':'BDA272','leaf':'739477',
           'grass':'A1B39A','earth':'9B927F','charcoal':'465D55','water':'79B8AD'}
materials={}
for name,h in PALETTE.items():
    m=bpy.data.materials.new(name);m.use_nodes=True
    col=[int(h[i:i+2],16)/255 for i in (0,2,4)]
    # Blender takes linear material colors; convert the deliberately chosen sRGB palette.
    linear=[((v+.055)/1.055)**2.4 if v>.04045 else v/12.92 for v in col]
    p=m.node_tree.nodes.get('Principled BSDF');p.inputs['Base Color'].default_value=(*linear,1)
    p.inputs['Roughness'].default_value=.88
    materials[name]=m

def reset():
    bpy.ops.object.select_all(action='SELECT');bpy.ops.object.delete(use_global=False)

def finish(o,mat,bevel=0):
    o.data.materials.append(materials[mat])
    if bevel:
        b=o.modifiers.new('Soft edges','BEVEL');b.width=bevel;b.segments=3
        b.affect='EDGES';bpy.context.view_layer.objects.active=o
        bpy.ops.object.modifier_apply(modifier=b.name)
    for p in o.data.polygons:p.use_smooth=True
    n=o.modifiers.new('Weighted normals','WEIGHTED_NORMAL');n.keep_sharp=True;n.weight=40
    bpy.context.view_layer.objects.active=o
    bpy.ops.object.modifier_apply(modifier=n.name)
    return o

def box(name,pos,size,mat,bevel=.06):
    bpy.ops.mesh.primitive_cube_add(size=1,location=pos);o=bpy.context.object;o.name=name
    o.dimensions=size;bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)
    return finish(o,mat,min(bevel,min(size)*.42))

def cylinder(name,pos,radius,depth,mat,vertices=24):
    bpy.ops.mesh.primitive_cylinder_add(vertices=vertices,radius=radius,depth=depth,location=pos)
    o=bpy.context.object;o.name=name;return finish(o,mat,.035)

def sphere(name,pos,size,mat):
    bpy.ops.mesh.primitive_uv_sphere_add(segments=16,ring_count=8,radius=1,location=pos)
    o=bpy.context.object;o.name=name;o.scale=size
    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)
    return finish(o,mat)

def beam(name,a,b,radius,mat):
    a,b=Vector(a),Vector(b);o=cylinder(name,(a+b)/2,radius,(a-b).length,mat,12)
    o.rotation_euler=(b-a).to_track_quat('Z','Y').to_euler();return o

def rect_ring(name,w,d,r,z,h,thick,mat):
    verts=[];faces=[];steps=8
    def loop(ww,dd,rr,zz):
        for cx,cy,start in [(ww/2-rr,dd/2-rr,0),(-ww/2+rr,dd/2-rr,90),(-ww/2+rr,-dd/2+rr,180),(ww/2-rr,-dd/2+rr,270)]:
            for i in range(steps+1):
                a=math.radians(start+i*90/steps);verts.append((cx+rr*math.cos(a),cy+rr*math.sin(a),zz))
    loop(w,d,r,z);loop(w,d,r,z+h)
    loop(w-2*thick,d-2*thick,max(.1,r-thick),z+h)
    loop(w-2*thick,d-2*thick,max(.1,r-thick),z)
    n=4*(steps+1)
    for layer in range(4):
        for i in range(n):faces.append((layer*n+i,layer*n+(i+1)%n,((layer+1)%4)*n+(i+1)%n,((layer+1)%4)*n+i))
    mesh=bpy.data.meshes.new(name);mesh.from_pydata(verts,[],faces);mesh.update()
    o=bpy.data.objects.new(name,mesh);bpy.context.collection.objects.link(o);finish(o,mat,.025)
    return o

def tub(w,d,mat,private=False):
    rect_ring('Basin',w,d,min(w,d)*.32,.04,.8,.24,mat)
    rect_ring('Rim',w+.08,d+.08,min(w,d)*.32,.83,.13,.33,'cream' if private else mat)
    box('Basin floor',(0,0,.14),(w-.3,d-.3,.18),'teal',.2)
    box('Water',(0,0,.66),(w-.53,d-.53,.015),'water',.22)
    if not private:
        for yy in [-d*.3,d*.3]:box('Underwater bench',(0,yy,.35),(w*.62,.36,.22),mat)
    # Sculpted coping, low entry step, rolled towels and a little tray.
    box('Step',(0,-d/2-.25,.15),(w*.58,.52,.28),mat)
    box('Towel',(w*.22,-d/2,.97),(.5,.25,.13),'linen',.05)
    if mat=='cedar':
        rect_ring('Brass band',w+.035,d+.035,min(w,d)*.32,.23,.055,.08,'darkwood')
        rect_ring('Brass band',w+.035,d+.035,min(w,d)*.32,.6,.055,.08,'darkwood')
        for x in range(12):
            xx=-w*.4+x*w*.8/11
            box('Cedar stave',(xx,-d/2-.008,.46),(.012,.008,.6),'darkwood',0)
    if private:
        beam('Tap',(-w*.4,d*.24,.83),(-w*.4,d*.24,1.08),.04,'gold')
        beam('Tap',(-w*.4,d*.24,1.08),(-w*.4+.26,d*.24,1.08),.04,'gold')

def pavilion(w,d,mat='cream',roof=True):
    box('Room foundation',(0,0,.055),(w,d,.1),'stone')
    box('Wall back',(0,d/2-.1,1.27),(w,.18,2.5),mat)
    box('Wall side',(-w/2+.1,0,1.27),(.18,d,2.5),mat)
    box('Wall side',(w/2-.1,d*.25,1.27),(.18,d*.5,2.5),mat)
    for x in [-w/2+.12,w/2-.12]:
        box('Pillar',(x,-d/2+.12,1.22),(.22,.22,2.45),'wood')
    box('Lintel',(0,-d/2+.12,2.42),(w,.24,.24),'wood')
    if roof:
        # Sculpted gently curved roof, mirrored slopes. Matching model, not engine primitives.
        verts=[];faces=[];n=16
        for y in [-d/2-.27,d/2+.27]:
            for i in range(n+1):
                x=-w/2-.3+(w+.6)*i/n
                z=2.8+.53*math.cos(x/(w/2+.3)*math.pi/2)
                verts.append((x,y,z))
        for i in range(n):faces.append((i,i+1,n+2+i,n+1+i))
        m=bpy.data.meshes.new('roof');m.from_pydata(verts,[],faces);m.update()
        o=bpy.data.objects.new('Roof',m);bpy.context.collection.objects.link(o)
        s=o.modifiers.new('Roof thickness','SOLIDIFY');s.thickness=.13
        bpy.context.view_layer.objects.active=o;bpy.ops.object.modifier_apply(modifier=s.name)
        finish(o,'sage',.035)
        for yy in [-d/2-.27,d/2+.27]:
            for i in range(n):
                a=verts[i];b=verts[i+1]
                beam('Roof trim',(a[0],yy,a[2]-.04),(b[0],yy,b[2]-.04),.06,'wood')
        for i in range(12):
            yy=-d/2-.2+(d+.4)*i/11
            beam('Roof seam',(0,yy,3.35),(w/2+.3,yy,2.84),.02,'sage')
            beam('Roof seam',(0,yy,3.35),(-w/2-.3,yy,2.84),.02,'sage')

def export(name):
    # Merge authored pieces by material and visibility group. A sauna contains
    # many individual slats, but ships as a handful of meshes rather than 100 draws.
    groups={}
    for o in list(bpy.context.scene.objects):
        if o.type!='MESH':continue
        role='Water' if o.name.startswith('Water') else ('Roof' if o.name.startswith('Roof') else 'Body')
        mat=o.data.materials[0].name
        groups.setdefault((role,mat),[]).append(o)
    for (role,mat),pieces in groups.items():
        bpy.ops.object.select_all(action='DESELECT')
        for o in pieces:o.select_set(True)
        bpy.context.view_layer.objects.active=pieces[0]
        bpy.ops.object.join()
        o=bpy.context.object;o.name=role+'_'+mat
        bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)
    bpy.ops.object.select_all(action='SELECT')
    bpy.ops.export_scene.gltf(filepath=str(OUT/(name+'.glb')),export_format='GLB',export_yup=True,export_apply=True,export_extras=False)
    print('AUTHORED',name,flush=True)

