cylinder('Heater',(1.55,-1.3,.5),.4,.9,'charcoal')
for i in range(7):sphere('Sauna stone',(1.55+random.uniform(-.24,.24),-1.3+random.uniform(-.24,.24),.96),(.17,.15,.12),'stone')
export('sauna')
