cylinder('Toilet base',(.6,.65,.23),.26,.46,'linen');sphere('Porcelain',(.6,.54,.54),(.39,.53,.23),'linen')
box('Cistern',(.6,1.17,.7),(.7,.3,.75),'linen');box('Sink',(-.65,.88,.9),(.8,.65,.2),'linen')
